import com.shnewbs.deepprimal.core.lod.*; import java.util.*; public class CompareLod { public static void main(String[] a)throws Exception { int n=0; for(int k=0;k<5;k++)for(int f:new int[]{-64,320}){ var c=LodReductionChecks.scene(k,f);var b=BaselineLodMesher.build(c);var x=LodMesher.build(c);if(!LodReductionChecks.signature(List.of(b.fine(),b.medium(),b.coarse())).equals(LodReductionChecks.signature(List.of(x.fine(),x.medium(),x.coarse()))))throw new AssertionError();n++; }System.out.println("BASELINE_CANDIDATE_LOD_PASS signatures="+n); }}